context:
query RefundPaymentContext($id: ID!, $items: [RefundLineItemInput!], $shipping: Boolean!, $allItems: Boolean!) {
  order(id: $id) {
    id name presentmentCurrencyCode displayFinancialStatus taxesIncluded customer { id }
    totalPriceSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } totalReceivedSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } totalRefundedSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
    transactionsCount { count precision }
    transactions(first: 250) { id kind status gateway formattedGateway amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } }
    full: suggestedRefund(suggestFullRefund: true, refundShipping: $shipping) { amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  subtotalSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } discountedSubtotalSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } totalCartDiscountAmountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  totalTaxSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } totalDutiesSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  shipping { amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } taxSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } }
  suggestedTransactions { kind gateway formattedGateway
    amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
    parentTransaction { id kind status gateway manualPaymentGateway } } }
    selected: suggestedRefund(refundLineItems: $items, refundShipping: $shipping) { amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  subtotalSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } discountedSubtotalSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } totalCartDiscountAmountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  totalTaxSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } totalDutiesSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
  shipping { amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } taxSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } }
  suggestedTransactions { kind gateway formattedGateway
    amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } maximumRefundableSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
    parentTransaction { id kind status gateway manualPaymentGateway } } }
    withoutShipping: suggestedRefund(refundLineItems: $items, suggestFullRefund: $allItems, refundShipping: false) { amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } }
  }
}

refund:
mutation RefundWithMethods($input: RefundInput!) {
  refundCreate(input: $input) @idempotent(key: "__KEY__") {
    refund { id totalRefundedSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
      refundShippingLines(first: 250) { nodes { subtotalAmountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } taxAmountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } } pageInfo { hasNextPage } }
      transactions(first: 250) { nodes { id kind status gateway parentTransaction { id } amountSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } } } }
    order { id totalRefundedSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } } }
    userErrors { field message }
  }
}

credit:
mutation ExtraStoreCredit($id: ID!, $input: StoreCreditAccountCreditInput!) {
  storeCreditAccountCredit(id: $id, creditInput: $input) {
    storeCreditAccountTransaction { id amount { amount currencyCode } account { id } }
    userErrors { field message }
  }
}
